import { Component} from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-padre',
  templateUrl: './padre.component.html',
  styleUrls: ['./padre.component.css']
})
export class PadreComponent{

  public email: string = "";
  public compras: any[] = []; // Usando tipo any para las compras
  public totalCompras: number = 0;

  constructor(public misComprasService: MisComprasService, public usuarioService: UsuarioService){}

  recogerCompras() {
    this.email = this.usuarioService.obtenerEmailUsuarioLogeado();

    if (this.email) {
      this.misComprasService.obtenerComprasUsuario(this.email).subscribe(
        (res: any) => { // Maneja la respuesta como cualquier tipo
          this.compras = res; // Asumiendo que res es un arreglo directamente
          this.calcularTotalCompras(); // Calcula el total después de cargar las compras
        },
        error => {
          console.error('Error al obtener las compras:', error);
        }
      );
    } else {
      console.warn('No se ha establecido un email de usuario.');
    }
  }


  calcularTotalCompras() {
    this.totalCompras = this.compras.reduce((total, compra) => total + compra.total, 0);
  }

}
